"use client";

import { useEffect } from "react";

const WORDMARK = String.raw`
 █████╗ ███████╗██╗     ██╗  ██╗ █████╗ ██████╗ ████████╗
██╔══██╗╚══███╔╝██║     ██║  ██║██╔══██╗██╔══██╗╚══██╔══╝
███████║  ███╔╝ ██║     ███████║███████║██████╔╝   ██║
██╔══██║ ███╔╝  ██║     ██╔══██║██╔══██║██╔══██╗   ██║
██║  ██║███████╗███████╗██║  ██║██║  ██║██║  ██║   ██║
╚═╝  ╚═╝╚══════╝╚══════╝╚═╝  ╚═╝╚═╝  ╚═╝╚═╝  ╚═╝   ╚═╝`;

/** Small truths about how this site is built. One is picked per visit. */
const FACTS = [
  "The hero is not a video: it is liquid metal generated by a shader, then printed as thousands of halftone dots every frame.",
  "Page transitions grow out of the exact spot you clicked. Try clicking a corner.",
  "Everything that moves here is either dots or scrambled text. Nothing else is allowed.",
  "The site's ease curve is M0,0 C0.82,0.08 0.29,1 1,1. It is used for almost every movement.",
  "The footer wordmark is rasterised once, then rebuilt from dots sized by how much of each letter covers them.",
  "The logo turns into a string of dots near your cursor. Go back to the index and wave at it.",
  "There are no screenshots of client work here on purpose: every client and employer is anonymised.",
];

/** Printed once per page load, not once per StrictMode mount. */
let printed = false;

/**
 * A note for whoever opens the console: the wordmark in ASCII, one fact
 * about how the site works, and a way to get in touch.
 */
const ConsoleEgg = () => {
  useEffect(() => {
    if (printed) return;
    printed = true;

    const fact = FACTS[Math.floor(Math.random() * FACTS.length)];
    const mono = "font-family: ui-monospace, monospace;";

    console.log(
      `%c${WORDMARK}`,
      `${mono} color: #fff; background: #0a0a0a; line-height: 1.1;`,
    );
    console.log(
      "%cHello, fellow source-reader.%c\n\nFun fact: " + fact,
      `${mono} font-weight: bold; font-size: 13px;`,
      `${mono} font-size: 12px; color: #999;`,
    );
    console.log(
      "%cLooking for a frontend engineer? mariodaruranto68@gmail.com",
      `${mono} font-size: 12px; text-decoration: underline;`,
    );
  }, []);

  return null;
};

export default ConsoleEgg;
